import { Chess } from 'chess.js'
import { posKey } from './tree'

/** position key -> [ECO, name], generated by scripts/build-openings.mjs */
export type Book = Record<string, [string, string]>

let cached: Promise<Book> | null = null

/** Loaded lazily so the ~450 KB book stays out of the main bundle. */
export function loadBook(): Promise<Book> {
  return (cached ??= import('./book.json').then((m) => m.default as unknown as Book))
}

export interface BookInfo {
  eco: string
  name: string
  /** Full move number of the last book position when the current one is not in the book. */
  leftAtMove: number | null
}

/** Deepest named opening along the move path, or null if no position matched. */
export function lookupPath(book: Book, path: string[]): BookInfo | null {
  const chess = new Chess()
  let found: { eco: string; name: string; ply: number } | null = null
  const check = (ply: number) => {
    const hit = book[posKey(chess.fen())]
    if (hit) found = { eco: hit[0], name: hit[1], ply }
  }
  check(0)
  for (let i = 0; i < path.length; i++) {
    chess.move(path[i])
    check(i + 1)
  }
  if (!found) return null
  const f = found as { eco: string; name: string; ply: number }
  const inBook = f.ply === path.length
  return {
    eco: f.eco,
    name: f.name,
    leftAtMove: inBook ? null : Math.floor(f.ply / 2) + 1,
  }
}
